        )
        .await;

        let app = ctx.create_app().await;

        // With circuit breaker disabled, should always see 500 (never 503)
        for _ in 0..5 {
            let payload = json!({
                "text": "Test disabled CB",
                "stream": false
            });

            let req = Request::builder()
                .method("POST")
